	private static RepositoryInfo repositoryInfo(String id, String description, boolean readable, boolean writable) {
		RepositoryInfo info = new RepositoryInfo();
		info.setId(id);
		info.setDescription(description);
		info.setReadable(readable);
		info.setWritable(writable);
		return info;
	}

	private static Collection<RepositoryInfo> guardedRepositoryInfos(List<RepositoryInfo> values,
			AtomicInteger consumed, AtomicBoolean firstWritten) {
		return new AbstractCollection<>() {
			@Override
			public Iterator<RepositoryInfo> iterator() {
				return new Iterator<>() {
					@Override
					public boolean hasNext() {
						if (consumed.get() > 0 && !firstWritten.get()) {
							throw new IllegalStateException(
									"next repository requested before first result reached writer");
						}
						return consumed.get() < values.size();
					}

					@Override
					public RepositoryInfo next() {
						if (!hasNext()) {
							throw new NoSuchElementException();
						}
						return values.get(consumed.getAndIncrement());
					}
				};
			}

			@Override
			public int size() {
				return values.size();
			}
		};
	}

	private static MockHttpServletRequest request(RepositoryConnection connection) {
		Repository repository = mock(Repository.class);
		when(repository.getConnection()).thenReturn(connection);
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/repositories/test/contexts");
		request.setAttribute("repository", repository);
		request.addHeader("Accept", "application/sparql-results+json");
		return request;
	}

	private static <T> CloseableIteration<T> guardedSource(List<T> values, AtomicInteger consumed,
			AtomicBoolean firstWritten) {
		@SuppressWarnings("unchecked")
		CloseableIteration<T> source = mock(CloseableIteration.class);
		when(source.hasNext()).thenAnswer(invocation -> {
			if (consumed.get() > 0 && !firstWritten.get()) {
				throw new IllegalStateException("next metadata item requested before first result reached writer");
			}
			return consumed.get() < values.size();
		});
		when(source.next()).thenAnswer(invocation -> values.get(consumed.getAndIncrement()));
		return source;
	}

	private static List<BindingSet> renderWithRecordingWriter(ModelAndView result, MockHttpServletRequest request,
			MockHttpServletResponse response, AtomicBoolean firstWritten, boolean fail) throws Exception {
		List<BindingSet> written = new ArrayList<>();
		TupleQueryResultWriter writer = mock(TupleQueryResultWriter.class);
		when(writer.getSupportedSettings()).thenReturn(Set.of());
		doAnswer(invocation -> {
			BindingSet row = invocation.getArgument(0);
			written.add(row);
			firstWritten.set(true);
			if (fail) {
				throw new TupleQueryResultHandlerException("writer failed");
			}
			return null;
		}).when(writer).handleSolution(any());
		TupleQueryResultWriterFactory factory = mock(TupleQueryResultWriterFactory.class);
		when(factory.getTupleQueryResultFormat()).thenReturn(TupleQueryResultFormat.JSON);
		when(factory.getWriter(any())).thenReturn(writer);
		result.getModel().put(QueryResultView.FACTORY_KEY, factory);
		result.getView().render(result.getModel(), request, response);
		return written;
	}
